// Normaliza a origem do disparo: agendado (fim do dia, chat fixo da Michelle) ou
// sob demanda (/resumo, responde no mesmo chat de onde veio o comando).
const viaComando = $input.first().json.message !== undefined;
const chatId = viaComando ? $input.first().json.message.chat.id : '749277207';
return [{ json: { chatId } }];

// Monta o resumo do dia corrente a partir do log de eventos (seção 7.3).
// Cada entrada do log tem { timestamp, fase, resumo }. Soma os campos numéricos
// e concatena os arrays (ex.: alertasEncerramento) de todas as execuções de hoje.

function parseBinaryJson(item) {
  if (!item || !item.binary || !item.binary.data) return [];
  try {
    return JSON.parse(Buffer.from(item.binary.data.data, 'base64').toString('utf8'));
  } catch (e) {
    return [];
  }
}

const log = parseBinaryJson($('Ler log_diario.json').first());
const chatId = $('Resolver chat de destino').first().json.chatId;

const hojeISO = new Date().toISOString().slice(0, 10);
const entradasHoje = log.filter((e) => (e.timestamp || '').slice(0, 10) === hojeISO);

if (entradasHoje.length === 0) {
  return [{ json: { chatId, texto: '📅 Resumo do dia (' + hojeISO.split('-').reverse().join('/') + ')\n\nNenhuma execução registrada hoje ainda.' } }];
}

const total = {};
const alertasEncerramento = [];
const porFase = {};

for (const entrada of entradasHoje) {
  const fase = entrada.fase || 'desconhecida';
  porFase[fase] = (porFase[fase] || 0) + 1;
  const r = entrada.resumo || {};
  for (const chave of Object.keys(r)) {
    if (typeof r[chave] === 'number') {
      total[chave] = (total[chave] || 0) + r[chave];
    } else if (Array.isArray(r[chave]) && chave === 'alertasEncerramento') {
      alertasEncerramento.push(...r[chave]);
    }
  }
}

const linhas = [
  '📅 *Resumo do dia* (' + hojeISO.split('-').reverse().join('/') + ')',
  '',
  '*Execuções rodadas:* ' + entradasHoje.length + ' (' + Object.entries(porFase).map(([f, n]) => f + ': ' + n).join(', ') + ')',
  '',
  '*Pedidos/cobranças*',
  '• Rascunhos criados: ' + (total.rascunhosCriados || 0),
  '• Envios diretos: ' + (total.enviosDiretos || 0),
  '',
  '*Pendências*',
  '• Pendentes de contrato: ' + (total.pendentesContrato || 0),
  '• Com lacuna de informação (FALTA INFORMAÇÃO): ' + (total.comLacunaInformacao || 0),
  '• Situações não mapeadas (alertadas): ' + (total.alertasSituacaoNaoMapeada || 0),
  '• Correções de contrato aplicadas: ' + (total.correcoesContrato || 0),
  '',
  '*Ciclos encerrados sem resposta:* ' + alertasEncerramento.length,
];
if (alertasEncerramento.length > 0) {
  linhas.push(...alertasEncerramento.map((a) => '  - ' + (a.colaboradorOuFornecedor || '?') + ' (' + (a.projetoId || '?') + ')'));
}

return [{ json: { chatId, texto: linhas.join('\n') } }];
